            continue
        # avoid obstacles if provided as set/list of coords
        if isinstance(obstacles, (set, list)):
            if (nx, ny) in obstacles:
                continue
        # simple: avoid landing on opponent
        if (nx, ny) == opp:
            continue
        score = 0
        # closeness to resource
        if target_res is not None:
            score -= dist((nx,ny), target_res) * 2
        # proximity to opponent: prefer farther
        score -= dist((nx,ny), opp)
        # prefer not staying if there is nothing to do
        if mv == [0,0]:
            score += 0  # neutral
        if score > best_score:
            best_score = score
            best = [mv[0], mv[1]]

    if best is None:
        # fallback: stay
        return [0, 0]
    return best

